import json, os, re, uuid
from datetime import datetime, timezone
import boto3
TABLE=boto3.resource('dynamodb').Table(os.environ['TABLE_NAME'])
SNS=boto3.client('sns')
TOPIC=os.environ['TOPIC_ARN']
ORIGIN=os.environ['ALLOWED_ORIGIN']
EMAIL_RE=re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')
INTENTS={'program_interest','partnership','media','general'}
PROVINCES={'AB','BC','MB','NB','NL','NS','NT','NU','ON','PE','QC','SK','YT','Outside Canada'}
PROGRAMS={'Applied AI','Cybersecurity GRC','AI Governance','Cloud','Not sure yet',''}
def response(code, body):
 return {'statusCode':code,'headers':{'content-type':'application/json','access-control-allow-origin':ORIGIN,'cache-control':'no-store'},'body':json.dumps(body)}
def clean(v,n=500):
 return str(v or '').strip()[:n]
def handler(event, context):
 method=event.get('requestContext',{}).get('http',{}).get('method','')
 path=event.get('rawPath','')
 if method=='POST' and path.endswith('/submissions'):
  try: data=json.loads(event.get('body') or '{}')
  except: return response(400,{'message':'Invalid request.'})
  if clean(data.get('website')): return response(202,{'message':'Received.'})
  intent=clean(data.get('intent'),40); name=clean(data.get('name'),120); email=clean(data.get('email'),180).lower(); province=clean(data.get('province'),40); program=clean(data.get('program'),80)
  if intent not in INTENTS or len(name)<2 or not EMAIL_RE.match(email) or province not in PROVINCES or program not in PROGRAMS or data.get('consent') is not True: return response(400,{'message':'Please review the required fields.'})
  sid=str(uuid.uuid4()); created=datetime.now(timezone.utc).isoformat()
  item={'submissionId':sid,'createdAt':created,'intent':intent,'name':name,'email':email,'province':province,'program':program,'organization':clean(data.get('organization'),160),'role':clean(data.get('role'),120),'message':clean(data.get('message'),3000),'source':clean(data.get('source'),120)}
  TABLE.put_item(Item=item)
  subject='SozoRock Canada: '+intent.replace('_',' ').title()
  body='New SozoRock Canada submission\n\nType: '+intent+'\nName: '+name+'\nEmail: '+email+'\nProvince/Territory: '+province+'\nProgram: '+program+'\nOrganization: '+item['organization']+'\nRole: '+item['role']+'\n\n'+item['message']+'\n\nSubmission ID: '+sid
  SNS.publish(TopicArn=TOPIC,Subject=subject[:100],Message=body)
  return response(201,{'message':'Thank you. Your submission has been received.'})
 if method=='GET' and path.endswith('/admin/submissions'):
  claims=event.get('requestContext',{}).get('authorizer',{}).get('jwt',{}).get('claims',{})
  groups=str(claims.get('cognito:groups',''))
  if 'Admins' not in groups: return response(403,{'message':'Forbidden.'})
  result=TABLE.scan(Limit=200); items=sorted(result.get('Items',[]),key=lambda x:x.get('createdAt',''),reverse=True)
  return response(200,{'items':items})
 return response(404,{'message':'Not found.'})
